function o(t){return t.split(``).map(e=>e.normalize(`NFD`).charAt(0).toLowerCase()).join(``)}function l(t,e){return o(t).includes(o(e.trim()))}function f(t,e){let r=o(e.trim());if(!r)return[{text:t,hit:!1}];let h=o(t),s=[],n=0;for(let i=h.indexOf(r);i!==-1;i=h.indexOf(r,n))i>n&&s.push({text:t.slice(n,i),hit:!1}),s.push({text:t.slice(i,i+r.length),hit:!0}),n=i+r.length;return n<t.length&&s.push({text:t.slice(n),hit:!1}),s}export{l as n,f as t};